// Parse the OpenAI response
const input = $input.first().json;
let parsedData;

try {
  // The response from OpenAI node in n8n typically comes as a text field
  if (typeof input.text === 'string') {
    parsedData = JSON.parse(input.text);
  } else if (typeof input.response === 'string') {
    parsedData = JSON.parse(input.response);
  } else if (typeof input === 'string') {
    parsedData = JSON.parse(input);
  } else if (input.message?.content) {
    // Sometimes it's in message.content
    parsedData = typeof input.message.content === 'string' 
      ? JSON.parse(input.message.content) 
      : input.message.content;
  } else if (input.jobs) {
    // It might already be parsed
    parsedData = input;
  } else {
    // Try to find any string field that looks like JSON
    const jsonString = Object.values(input).find(val => 
      typeof val === 'string' && val.includes('"jobs"')
    );
    if (jsonString) {
      parsedData = JSON.parse(jsonString);
    } else {
      throw new Error('Could not find JSON data in response');
    }
  }

  console.log('Successfully parsed data with', parsedData.jobs?.length, 'jobs');

} catch (error) {
  console.error('Error parsing OpenAI response:', error);
  console.log('Raw input:', JSON.stringify(input, null, 2));

  // Return error with debug info
  return [{
    json: {
      error: 'Failed to parse OpenAI response',
      errorMessage: error.message,
      rawResponse: input,
      debugInfo: 'Check the console logs for the raw response structure'
    }
  }];
}

// Extract jobs and pagination info
const jobs = parsedData.jobs || [];
const pagination = parsedData.pagination || { hasMore: false, nextStartIndex: 1 };

// Filter for jobs with emails only
const jobsWithEmails = jobs.filter(job => job.hasEmail === true);

console.log(`Found ${jobsWithEmails.length} jobs with emails out of ${jobs.length} total`);

// Prepare bulk array for webhook
const bulkJobsArray = jobsWithEmails.map(job => ({
  jobTitle: job.jobTitle || 'N/A',
  company: job.company || 'N/A',
  location: job.location || 'N/A',
  emails: Array.isArray(job.emails) ? job.emails.join(', ') : (job.emails || 'No email'),
  emailType: job.emailType || 'recruiter',
  isRemote: job.isRemote || false,
  salary: job.salary || 'Not specified',
  link: job.link || '',
  snippet: (job.snippet || '').substring(0, 200),
  scrapedDate: job.scrapedDate || new Date().toISOString(),
  secretToken: '046801ecc26b566bb35515f48bfb775ef2d909ca2e78e667613b4cdcf65fc831'
}));

// If no results with emails, return a message
if (bulkJobsArray.length === 0) {
  console.log('No jobs with emails found in this batch');
  return [{
    json: {
      message: 'No jobs with emails found in this batch',
      totalJobs: jobs.length,
      jobsWithEmails: 0,
      pagination: pagination
    }
  }];
}

console.log(`Prepared ${bulkJobsArray.length} jobs for bulk webhook submission`);

// Return the bulk jobs wrapped in an object for n8n compatibility
// The HTTP Request node will then send this as the request body
return [{
  json: {
    jobs: bulkJobsArray,
    metadata: {
      totalProcessed: jobs.length,
      jobsWithEmails: bulkJobsArray.length,
      processedAt: new Date().toISOString(),
      pagination: pagination
    }
  }
}];
